<?php
require_once __DIR__.'/../core/Guard.php';ml_guard_shield(__FILE__);if(PHP_SAPI!=='cli'){ml_guard_deny();}require_once __DIR__.'/../core/Config.php';require_once __DIR__.'/../core/Sync.php';use Core\Sync;$a=array('task'=>'hourly');$b=false;$argv=isset($argv)?$argv:array();$c=array_slice($argv,1);$d='';$e=0;$f=count($c);while($e<$f){$g=(string)$c[$e];if($g==='--force'){$a['force']=true;$e++;continue;}if($g==='--quiet'||$g==='-q'){$b=true;$e++;continue;}if($g==='--dry'){$a['dry']=true;$e++;continue;}if($g==='--no-build'){$a['build']=0;$e++;continue;}if($g==='--build'){$a['build']=1;$e++;continue;}if($g==='--help'||$g==='-h'){echo"媒资资料库 · 每小时采集\n\n";echo"用法： php cron/sync_hourly.php [选项]\n\n";echo"  --limit=20 或 --limit 20        每个源本次最多入库多少条\n";echo"  --window=day 或 --window day    今日热榜（day|week）\n";echo"  --order=both 或 --order both    hot / popular / both\n";echo"  --sources=tmdb,hongguoduanju     只跑指定源\n";echo"  --interval=55                    与上次同步的最小间隔（分钟）\n";echo"  --max-requests=8                 单次上游请求总数硬闸\n";echo"  --force --no-build --dry --quiet\n";exit(0);}$h='';$i=null;$j=strpos($g,'=');if(strpos($g,'--')===0&&$j!==false){$h=substr($g,2,$j-2);$i=substr($g,$j+1);$e++;}elseif(strpos($g,'--')===0){$h=substr($g,2);if(!in_array($h,array('limit','window','order','interval','max-requests','sources'),true)){$d='未知参数：'.$g;break;}if($e+1>=$f||strpos((string)$c[$e+1],'--')===0){$d='参数缺少值：'.$g;break;}$i=$c[$e+1];$e+=2;}else{$d='无法识别的参数：'.$g;break;}switch($h){case'limit':$a['limit']=(int)$i;break;case'window':$a['window']=(string)$i;break;case'order':$a['order']=(string)$i;break;case'interval':$a['interval']=(int)$i;break;case'max-requests':$a['max_requests']=(int)$i;break;case'sources':$k=array();foreach(explode(',',(string)$i)as $l){$l=trim($l);if($l!==''){$k[]=$l;}}$a['sources']=$k;break;default:$d='未知参数：--'.$h;break 2;}}if($d!==''){fwrite(STDERR,$d."\n执行 --help 查看用法。\n");exit(1);}if(isset($a['window'])&&!in_array($a['window'],array('day','week'),true)){fwrite(STDERR,"--window 只能是 day 或 week。\n");exit(1);}if(isset($a['order'])&&!in_array($a['order'],array('hot','popular','both'),true)){fwrite(STDERR,"--order 只能是 hot、popular 或 both。\n");exit(1);}if(isset($a['limit'])&&($a['limit']<1||$a['limit']>200)){fwrite(STDERR,"--limit 范围必须是 1~200。\n");exit(1);}if(isset($a['interval'])&&($a['interval']<0||$a['interval']>1440)){fwrite(STDERR,"--interval 范围必须是 0~1440。\n");exit(1);}if(isset($a['max_requests'])&&($a['max_requests']<1||$a['max_requests']>60)){fwrite(STDERR,"--max-requests 范围必须是 1~60。\n");exit(1);}$m=Core\Config::get('sync',array());$n=(isset($m['hourly_enabled'])&&$m['hourly_enabled']!==''&&$m['hourly_enabled']!=='0'&&$m['hourly_enabled']!==0)?1:0;if(!isset($m['hourly_enabled'])||$m['hourly_enabled']===''||$m['hourly_enabled']==='1'||$m['hourly_enabled']===1){$n=1;}if(!$n){$o='每小时自动采集已关闭（后台 →「同步采集」→「每小时自动采集」开关）。本次跳过。';if($b){echo'SKIP  note='.$o."\n";}else{echo $o."\n";}exit(0);}if(!isset($a['limit'])){$p=isset($m['hourly_limit'])?(int)$m['hourly_limit']:5;$p=max(1,min(50,$p));$a['limit']=$p;}$q=Sync::run($a);if($b){echo sprintf("%s  inserted=%d skipped=%d fetched=%d requests=%d built=%d ms=%d%s\n",$q['ok']?'OK':'FAIL',(int)$q['inserted'],(int)$q['skipped_dup'],(int)$q['fetched'],(int)$q['requests'],(int)$q['built'],(int)$q['ms'],$q['reason']!==''?('  note='.$q['reason']):'');exit($q['ok']?0:1);}echo"==== 媒资资料库 · 采集开始 ".date('Y-m-d H:i:s')." ====\n";echo sprintf("参数：每源上限 %d 条 · 时间窗 %s · 口径 %s · 最低投票 %d · 重复处理 %s\n",(int)$q['params']['limit'],$q['params']['window'],$q['params']['order'],(int)$q['params']['min_votes'],$q['params']['dedupe']);echo"说明：按各源官方限制限流（TMDB 0.3s/请求、、红果短剧需配置），只取最热与最多人看的榜。\n\n";if(!empty($q['skipped'])){echo"[跳过] ".$q['reason']."\n";echo"本次未采集。（要立刻跑请加 --force）\n";exit(0);}foreach($q['sources']as $r){echo"── ".(isset($r['label'])?$r['label']:$r['source'])."\n";if($r['endpoints']){foreach($r['endpoints']as $s){echo sprintf("   · %-26s 抓到 %d 条%s\n",$s['path'],(int)$s['count'],$s['error']!==''?('   ✗ '.$s['error']):'');}}echo sprintf("   新增 %d · 重复跳过 %d · 低于票数门槛 %d · 请求 %d 次\n",(int)$r['inserted'],(int)$r['skipped_dup'],(int)$r['skipped_low'],(int)$r['requests']);if(isset($r['msg'])&&$r['msg']!==''){echo"   ⚠ ".$r['msg']."\n";}echo"\n";}echo sprintf("汇总：抓到 %d 条 → 新增 %d 条，重复跳过 %d 条，低于票数门槛 %d 条；上游请求 %d 次，静态页 %d 个，耗时 %.1fs\n",(int)$q['fetched'],(int)$q['inserted'],(int)$q['skipped_dup'],(int)$q['skipped_low'],(int)$q['requests'],(int)$q['built'],$q['ms']/1000);if($q['reason']!==''){echo"提示：".$q['reason']."\n";}if(!$q['ok']){echo"结果：失败（详见上面的提示）\n";}echo"==== 采集结束 ".date('Y-m-d H:i:s')." ====\n";exit($q['ok']?0:1);